    "index": 1,
    "modal": "Must",
    "text": "Each Jev request MUST carry exactly one record."
  },
  "record": {
    "id": "REQ-JEV-0202",
    "title": "One record and one location per request",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "Each Jev request MUST carry exactly one record."
        },
        {
          "modal": "Must",
          "text": "Each Jev request MUST carry exactly one location."
        },
        {
          "modal": "Must",
          "text": "A run over many pairs MUST send them as a stream of single requests."
        }
      ]
    },
    "rationale": "Jev judges one record and location at a time; packing records into one request hides\nwhich one failed. Batching is streaming single requests, which the batch\ncommand already does.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "A profile mapping one file to three records sends three requests.",
